; >S:INKEY; PUT "INKEY";; A CALL TO THIS ROUTINE; RETURNS THE ACC. WITH :-;; 0     = NO KEY PRESSED; 1-26  = A-Z;; 27    = SPACE; 28    = RETURN; 29    = DELETE;INKEY;LDA #0STA KEYVAL;INK1;LDA KEYVALASL ATAX;INC KEYVAL;LDA INKDAT,XTAY;LDA INKDAT+1,X;JSR KEYIT      ;* CHECK IT;BCC NOINKY     ;* NOT PRESSED;LDA KEYVAL     ;* RETURN WITH VAL;RTS;NOINKY;LDA KEYVALCMP #29BNE INK1;LDA #0;RTS;;INKDAT;.BYTE $FD,$04,$F7,$10,$FB,$10.BYTE $FB,$04,$FD,$40,$FB,$20.BYTE $F7,$04,$F7,$20,$EF,$02.BYTE $EF,$04,$EF,$20,$DF,$04.BYTE $EF,$10,$EF,$80,$EF,$40.BYTE $DF,$02,$7F,$40,$FB,$02.BYTE $FD,$20,$FB,$40,$F7,$40.BYTE $F7,$80.BYTE $FD,$02,$FB,$80,$F7,$02.BYTE $FD,$10.BYTE $7F,$10.BYTE $FE,$02,$FE,$01;;.END